import nodemailer, { type SendMailOptions, type Transporter } from 'nodemailer';
import type { Config } from '../../config.js';
import type { OutboundMessage } from '../../lib/message.js';
import type { SenderAdapter } from './types.js';

/** Maps our headers onto nodemailer's options; Content-Type and MIME-Version are generated by nodemailer. */
export function toMailOptions(msg: OutboundMessage): SendMailOptions {
  const h = { ...msg.headers };
  const take = (k: string): string | undefined => {
    const v = h[k];
    delete h[k];
    return v;
  };
  const options: SendMailOptions = {
    from: take('From'),
    to: take('To'),
    subject: take('Subject'),
    messageId: take('Message-ID'),
    inReplyTo: take('In-Reply-To'),
    references: take('References'),
  };
  delete h['Content-Type'];
  delete h['MIME-Version'];
  return { ...options, headers: h, text: msg.text };
}

export function createMailpitSender(transport: Pick<Transporter, 'sendMail'>): SenderAdapter {
  return {
    name: 'mailpit',
    async send(msg) {
      const info = (await transport.sendMail(toMailOptions(msg))) as { messageId?: string };
      return { provider_message_id: msg.headers['Message-ID'] as string, provider_ref: info.messageId };
    },
  };
}

const LOCAL_SINKS = new Set(['mailpit', 'localhost', '127.0.0.1', '::1']);

export function createMailpitSenderFromConfig(config: Config): SenderAdapter {
  // Sandbox sends skip the live-send gate, so they may only ever reach a local sink, never a real relay.
  if (!LOCAL_SINKS.has(config.smtpHost)) throw new Error(`sandbox mode only delivers to a local SMTP sink (mailpit, localhost), not ${config.smtpHost}`);
  return createMailpitSender(
    nodemailer.createTransport({
      host: config.smtpHost,
      port: config.smtpPort,
      secure: false,
      ignoreTLS: true,
    }),
  );
}
